#!/usr/bin/env python3
"""One-shot materializer for the accepted tdmem-0201 capability contract."""
from __future__ import annotations

import base64
import hashlib
import json
import zlib
from pathlib import Path

FILES = [
    (
        "product/contracts/memory-provider-v1/provider-registry-contract.json",
        "docs(contract): separate provider capability classes (tdmem-0201)",
        "eda519ba9504d8e5a4088ac226a7378f76218060014ca631af9062f14331d571",
        "",
    ),
    (
        "product/contracts/memory-provider-v1/provider-registry-contract.schema.json",
        "docs(contract): lock provider registry schema semantics (tdmem-0201)",
        "02c530d569f7a03f50e64502bd27bc070cd523d610d8a15809344589ce324043",
        "",
    ),
    (
        "product/contracts/memory-provider-v1/README.md",
        "docs(contract): document unknown capability round-trip (tdmem-0201)",
        "cd364c0f9bbd9c4e90ab3a67712f24aa878fce80c02b1cf67c3eb589d62a89ba",
        "",
    ),
    (
        "scripts/product/check-provider-registry-contract.py",
        "test(contract): validate provider capability semantics (tdmem-0201)",
        "930f68845f2418369ff154d01686d0d4ed78ff5b5daed1b05cf82f8ae419c4bd",
        "",
    ),
    (
        "tests/product_provider_registry_contract_test.py",
        "test(contract): cover provider registry drift (tdmem-0201)",
        "1433682b83719a370f560a806f8d671aec9b0ef5e1eeb126a0c40f28f88c2057",
        "",
    ),
]

manifest = []
for path_text, message, expected_sha256, payload in FILES:
    data = zlib.decompress(base64.b64decode(payload))
    actual = hashlib.sha256(data).hexdigest()
    if actual != expected_sha256:
        raise SystemExit(f"payload digest mismatch for {path_text}: {actual}")
    path = Path(path_text)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(data)
    manifest.append({"path": path_text, "message": message})

manifest_path = Path(".beads/operations/prepared-files.json")
manifest_path.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
Path(__file__).unlink()
